create table xxcus.xxfnd_roles (
    role_code             varchar2(30 byte) not null enable,
    application_code      varchar2(30 byte) not null enable,
    role_name             varchar2(200 byte) not null enable,
    description           varchar2(500 byte),
    view_sensitive_flag   varchar2(1 byte) default 'N' not null enable,
    enabled_flag          varchar2(1 byte) default 'Y' not null enable,
    created_by            varchar2(255 byte) not null enable,
    creation_date         timestamp(6) not null enable,
    last_updated_by       varchar2(255 byte) not null enable,
    last_update_date      timestamp(6) not null enable,
    last_update_login     varchar2(255 byte),
    object_version_number number default 1 not null enable
);

alter table xxcus.xxfnd_roles
    add constraint xxfnd_roles_ck1
        check ( view_sensitive_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxfnd_roles
    add constraint xxfnd_roles_ck2
        check ( enabled_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxfnd_roles
    add constraint xxfnd_roles_pk primary key ( role_code )
        using index enable;


